const input = $input.first()?.json ?? {};
const error = input.error ?? input.execution?.error ?? {};
const rawContext = error.context?.metadata?.blueprint ?? error.context?.blueprint ?? error.metadata?.blueprint ?? error.context ?? input.blueprint_context ?? {};

const redactString = (value) => String(value ?? '')
  .replace(/Bearer\s+[A-Za-z0-9._~+\/-]+=*/gi, 'Bearer [REDACTED]')
  .replace(/sb_(?:secret|publishable)_[A-Za-z0-9_-]+/gi, 'sb_[REDACTED]')
  .replace(/(?:apikey|api[_-]?key|token|password|secret)\s*[:=]\s*[^\s,;]+/gi, '[CREDENTIAL_REDACTED]')
  .replace(/eyJ[A-Za-z0-9_-]+\.eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+/g, '[JWT_REDACTED]')
  .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[EMAIL_REDACTED]');

const rawMessage = error.message ?? input.message ?? 'Unexpected workflow failure';
const message = redactString(rawMessage).slice(0, 1000);
const lower = message.toLowerCase();

let errorClass = 'UNKNOWN';
if (/unauthor|forbidden|jwt|auth|credential/.test(lower)) errorClass = 'AUTH';
else if (/429|rate.?limit|quota|too many requests/.test(lower)) errorClass = 'RATE_LIMIT';
else if (/timeout|timed out|etimedout|deadline/.test(lower)) errorClass = 'TIMEOUT';
else if (/schema|json|parse|structured output/.test(lower)) errorClass = 'SCHEMA';
else if (/validat|invalid input|bad request|400/.test(lower)) errorClass = 'VALIDATION';
else if (/409|conflict|duplicate|state version|concurrent/.test(lower)) errorClass = 'CONFLICT';
else if (/budget|transition limit|tool call limit|cost limit/.test(lower)) errorClass = 'BUDGET';
else if (/quality|citation|evidence gate|auditor/.test(lower)) errorClass = 'QUALITY';
else if (/you\.com|nebius|pinecone|supabase|provider|502|503|504|network|econn/.test(lower)) errorClass = 'PROVIDER';
else if (/internal|500|exception/.test(lower)) errorClass = 'INTERNAL';

const retryable = ['RATE_LIMIT', 'TIMEOUT', 'PROVIDER'].includes(errorClass);
const retryCount = Number(rawContext.retry_count ?? rawContext.retryCount ?? 0);
const retryExhausted = rawContext.retry_exhausted === true || rawContext.retryExhausted === true || retryCount >= 2 || !retryable;
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const ownerId = rawContext.owner_id ?? rawContext.ownerId ?? null;
const projectId = rawContext.project_id ?? rawContext.projectId ?? null;
const runId = rawContext.run_id ?? rawContext.runId ?? null;
const workflowName = input.workflow?.name ?? input.execution?.workflowName ?? 'Unknown Blueprint workflow';
const nodeName = input.lastNodeExecuted ?? input.node?.name ?? error.node?.name ?? null;
const executionId = input.execution?.id ?? null;
const correlationId = rawContext.correlation_id ?? rawContext.correlationId ?? executionId ?? `bp-error-${Date.now()}`;
const hasOwnerContext = uuid.test(String(ownerId ?? '')) && (!projectId || uuid.test(String(projectId))) && (!runId || uuid.test(String(runId)));

const safeMessages = {
  AUTH: 'Authentication failed safely. Please sign in again.',
  VALIDATION: 'The request could not be validated. Please review the submitted information.',
  RATE_LIMIT: 'A research service is temporarily busy. The run has been stopped safely.',
  TIMEOUT: 'A research step exceeded its time limit. The run has been stopped safely.',
  SCHEMA: 'An agent returned an invalid structured response. The run has been stopped safely.',
  QUALITY: 'The evidence quality gate did not pass. Human review is required.',
  CONFLICT: 'Another worker updated this run first. The stale operation was rejected.',
  BUDGET: 'The run reached a configured safety limit and was stopped.',
  PROVIDER: 'A required research service failed. Successful work has been preserved.',
  INTERNAL: 'An internal workflow step failed. The run has been stopped safely.',
  UNKNOWN: 'An unexpected workflow error occurred. The run has been stopped safely.'
};

const recovery = retryable && !retryExhausted
  ? 'Retry only from the owning workflow within its configured limit.'
  : (errorClass === 'AUTH' || errorClass === 'VALIDATION'
      ? 'Return a safe response without automatic replay.'
      : 'Inspect the redacted audit record before any replay.');

return [{ json: {
  has_owner_context: hasOwnerContext,
  owner_id: hasOwnerContext ? ownerId : null,
  project_id: hasOwnerContext ? projectId : null,
  run_id: hasOwnerContext ? runId : null,
  error_class: errorClass,
  retryable,
  retry_count: retryCount,
  retry_exhausted: retryExhausted,
  workflow_name: redactString(workflowName).slice(0, 300),
  node_name: redactString(nodeName).slice(0, 300) || null,
  safe_message: safeMessages[errorClass],
  redacted_details: { redacted_message: message, execution_id: executionId, source: 'n8n_error_trigger', classification_version: 'bp-error-v1' },
  recovery_action: recovery,
  correlation_id: redactString(correlationId).slice(0, 300),
  payload_reference: { execution_id: executionId, workflow_id: input.workflow?.id ?? input.execution?.workflowId ?? null, replay_source: 'n8n_execution' }
} }];

const response = $input.first()?.json ?? {};
const failed = response.error ?? null;
return [{ json: {
  audit_recorded: !failed && response.recorded === true,
  safe_message: failed ? 'The database audit writer failed. Review this n8n execution before replay.' : 'The failure was recorded safely.',
  error_id: response.error_id ?? null,
  dead_letter_id: response.dead_letter_id ?? null,
  run_id: response.run_id ?? null,
  run_status: response.run_status ?? null,
  correlation_id: response.correlation_id ?? null,
  audit_writer_error_class: failed ? (failed.name ?? failed.message ?? 'audit_writer_failed') : null
} }];

const item = $input.first()?.json ?? {};
return [{ json: {
  audit_recorded: false,
  reason: 'NO_VERIFIED_OWNER_CONTEXT',
  safe_message: item.safe_message ?? 'An unexpected workflow error occurred safely.',
  error_class: item.error_class ?? 'UNKNOWN',
  workflow_name: item.workflow_name ?? 'Unknown Blueprint workflow',
  node_name: item.node_name ?? null,
  correlation_id: item.correlation_id ?? null,
  action: 'Review the redacted n8n execution. Do not create a founder-owned Supabase row without verified ownership.'
} }];
